class KaamError(Exception):
    """Base class for every error Kaam reports to the user."""


class ValidationError(KaamError):
    """Bad input: an empty title, an unknown priority, a malformed date."""


class TaskNotFound(KaamError):
    """No task has the requested id."""


class StorageError(KaamError):
    """The task file is unreadable or corrupt."""

