import json
import os
from pathlib import Path

from errors import StorageError
from models import Task


class MemoryStorage:
    """Keeps tasks in memory as plain dicts, like a real store would. Perfect for tests."""

    def __init__(self):
        self.rows: list[dict] = []

    def load(self) -> list[Task]:
        return [Task.from_dict(row) for row in self.rows]

    def save(self, tasks: list[Task]) -> None:
        self.rows = [task.to_dict() for task in tasks]


class JsonStorage:
    """Keeps tasks in a JSON file, written atomically."""

    def __init__(self, path: str):
        self.path = Path(path)

    def load(self) -> list[Task]:
        if not self.path.exists():
            return []
        try:
            rows = json.loads(self.path.read_text(encoding="utf-8"))
            return [Task.from_dict(row) for row in rows]
        except (json.JSONDecodeError, KeyError, ValueError) as err:
            raise StorageError(f"{self.path} is corrupt ({type(err).__name__})") from err

    def save(self, tasks: list[Task]) -> None:
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps([t.to_dict() for t in tasks], indent=2), encoding="utf-8")
        os.replace(tmp, self.path)

