from datetime import date, timedelta

from errors import TaskNotFound, ValidationError
from models import Priority, Task


class TaskService:
    def __init__(self, storage):
        self.storage = storage

    def add(self, title: str, priority: str = "medium", due: str | None = None) -> Task:
        title = title.strip()
        if not 1 <= len(title) <= 80:
            raise ValidationError("title must be 1 to 80 characters")
        try:
            level = Priority[priority.upper()]
        except KeyError:
            raise ValidationError(f"priority must be low, medium or high, not {priority!r}") from None
        try:
            due_date = date.fromisoformat(due) if due else None
        except ValueError:
            raise ValidationError(f"due date must look like 2026-10-25, not {due!r}") from None
        tasks = self.storage.load()
        task = Task(max((t.id for t in tasks), default=0) + 1, title, level, due_date)
        self.storage.save(tasks + [task])
        return task

    def complete(self, task_id: int) -> Task:
        tasks = self.storage.load()
        task = self._find(tasks, task_id)
        task.done = True
        self.storage.save(tasks)
        return task

    def delete(self, task_id: int) -> Task:
        tasks = self.storage.load()
        task = self._find(tasks, task_id)
        self.storage.save([t for t in tasks if t.id != task_id])
        return task

    def pending(self) -> list[Task]:
        open_tasks = [t for t in self.storage.load() if not t.done]
        return sorted(open_tasks, key=lambda t: (-t.priority.value, t.due or date.max, t.id))

    def due_soon(self, today: date, days: int = 3) -> list[Task]:
        limit = today + timedelta(days=days)
        return [t for t in self.pending() if t.due and t.due <= limit]

    def all(self) -> list[Task]:
        return self.storage.load()

    @staticmethod
    def _find(tasks: list[Task], task_id: int) -> Task:
        for task in tasks:
            if task.id == task_id:
                return task
        raise TaskNotFound(f"no task with id {task_id}")

